/**
 * Definition for a binary tree node. public class TreeNode { int val; TreeNode left; TreeNode
 * right; TreeNode() {} TreeNode(int val) { this.val = val; } TreeNode(int val, TreeNode left,
 * TreeNode right) { this.val = val; this.left = left; this.right = right; } }
 */
class Solution {
  public boolean isValidSequence(TreeNode root, int[] arr) {
    return findPath(root, arr, 0);
  }

  private boolean findPath(TreeNode root, int[] sequence, int index) {
    if (root == null || index == sequence.length) return false;

    if (sequence[index] != root.val) return false;

    if (root.left == null && root.right == null && index == sequence.length - 1) return true;

    return findPath(root.left, sequence, index + 1) || findPath(root.right, sequence, index + 1);
  }
}
